@Fold.fold_step_vis
     : forall (E MN T : Type -> Type) (MT : Monad.Monad T) (handle : forall X : Type, E X -> T X)
         (sample : forall X : Type, MN X -> T X) (A X : Type) (e : E X)
         (k : X -> PTreeDefinition.ptree E MN A),
       @Fold.fold_step E MN T MT handle sample A
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.VisF E MN A (PTreeDefinition.ptree E MN A) X e k
         |} =
       @Monad.bind T MT X (PTreeDefinition.ptree E MN A + A) (handle X e)
         (fun x : X =>
          @Monad.ret T MT (PTreeDefinition.ptree E MN A + A)
            (@inl (PTreeDefinition.ptree E MN A) A (k x)))

@Fold.fold_step_prob
     : forall (E MN T : Type -> Type) (MT : Monad.Monad T) (handle : forall X : Type, E X -> T X)
         (sample : forall X : Type, MN X -> T X) (A X : Type) (mu : MN X)
         (k : X -> PTreeDefinition.ptree E MN A),
       @Fold.fold_step E MN T MT handle sample A
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.ProbF E MN A (PTreeDefinition.ptree E MN A) X mu k
         |} =
       @Monad.bind T MT X (PTreeDefinition.ptree E MN A + A) (sample X mu)
         (fun x : X =>
          @Monad.ret T MT (PTreeDefinition.ptree E MN A + A)
            (@inl (PTreeDefinition.ptree E MN A) A (k x)))

