@StateFold.state_effect_forward
     : forall (S : Type) (E T : Type -> Type) (MT : Monad.Monad T)
         (handle : forall X : Type, E X -> T X) (X : Type) (e : E X) (s : S),
       @StateFold.state_effect S E T MT handle X (@Sum.inr1 (State.stateE S) E X e) s =
       @Monad.bind T MT X (S * X) (handle X e) (fun x : X => @Monad.ret T MT (S * X) (s, x))

@StateFold.state_sample_preserves_state
     : forall (S : Type) (MN T : Type -> Type) (MT : Monad.Monad T)
         (sample : forall X : Type, MN X -> T X) (X : Type) (mu : MN X)
         (s : S),
       @StateFold.state_sample S MN T MT sample X mu s =
       @Monad.bind T MT X (S * X) (sample X mu) (fun x : X => @Monad.ret T MT (S * X) (s, x))

@Runner.run_sound
     : forall (MN : Type -> Type) (Seed : Type)
         (sample : forall X : Type, MN X -> Seed -> Runner.draw_result X * Seed)
         (A : Type) (fuel : nat) (t : PTreeDefinition.ptree Sum.void1 MN A)
         (seed : Seed) (result : Runner.outcome A) (seed' : Seed),
       @Runner.run MN Seed sample A fuel t seed = (result, seed') ->
       @Runner.finished A result -> @Runner.executes MN Seed sample A t seed result seed'

@Runner.run_finished_iff
     : forall (MN : Type -> Type) (Seed : Type)
         (sample : forall X : Type, MN X -> Seed -> Runner.draw_result X * Seed)
         (A : Type) (t : PTreeDefinition.ptree Sum.void1 MN A) (seed : Seed)
         (result : Runner.outcome A) (seed' : Seed),
       @Runner.executes MN Seed sample A t seed result seed' <->
       @Runner.finished A result /\
       (exists fuel : nat, @Runner.run MN Seed sample A fuel t seed = (result, seed'))

@Runner.run_finished_more_fuel
     : forall (MN : Type -> Type) (Seed : Type)
         (sample : forall X : Type, MN X -> Seed -> Runner.draw_result X * Seed)
         (A : Type) (n m : nat) (t : PTreeDefinition.ptree Sum.void1 MN A)
         (seed : Seed) (result : Runner.outcome A) (seed' : Seed),
       n <= m ->
       @Runner.run MN Seed sample A n t seed = (result, seed') ->
       @Runner.finished A result -> @Runner.run MN Seed sample A m t seed = (result, seed')

