@Runner.finished_iff_semantic_result
     : forall (A : Type) (r : Runner.outcome A),
       @Runner.finished A r <->
       (exists result : Runner.semantic_result A,
          @Runner.outcome_view A r = @inl (Runner.semantic_result A) Runner.runner_failure result)

@Runner.unfinished_iff_runner_failure
     : forall (A : Type) (r : Runner.outcome A),
       ~ @Runner.finished A r <->
       (exists failure : Runner.runner_failure,
          @Runner.outcome_view A r = @inr (Runner.semantic_result A) Runner.runner_failure failure)

@Runner.run_result_iff
     : forall (MN : Type -> Type) (Seed : Type)
         (sample : forall X : Type, MN X -> Seed -> Runner.draw_result X * Seed)
         (A : Type) (t : PTreeDefinition.ptree Sum.void1 MN A) (seed : Seed)
         (result : Runner.semantic_result A) (seed' : Seed),
       @Runner.executes_result MN Seed sample A t seed result seed' <->
       (exists fuel : nat,
          @Runner.run MN Seed sample A fuel t seed =
          (@Runner.outcome_of_view A (@inl (Runner.semantic_result A) Runner.runner_failure result),
           seed'))

@Runner.Outcome.typed_result_agrees_with_existing_runner
     : forall (MN : Type -> Type) (Seed A : Type)
         (sample : forall X : Type, MN X -> Seed -> Runner.draw_result X * Seed)
         (t : PTreeDefinition.ptree Sum.void1 MN A) (seed : Seed)
         (result : Runner.semantic_result A) (seed' : Seed),
       @Runner.executes_result MN Seed sample A t seed result seed' <->
       (exists n : nat,
          @Runner.run MN Seed sample A n t seed =
          (@Runner.outcome_of_view A (@inl (Runner.semantic_result A) Runner.runner_failure result),
           seed'))

