         (ST : MonadSample.MonadSample MN T) (handle : forall X : Type, E X -> T X)
         (A : Type) (t : PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A),
       @StateFold.interp_state S E MN T MT IT ST handle A t =
       @StateFold.fold_state S E MN T MT IT handle
         (fun (X : Type) (mu : MN X) => @MonadSample.msample MN T ST X mu) A t

