         (ST : MonadSample.MonadSample MN T) (QT : Monad.Eq1 T),
       @Monad.Eq1Equivalence T MT QT ->
       @Monad.MonadLawsE T QT MT ->
       forall handle : forall X : Type, E X -> T X,
       @IterationLaws.iteration_uniform T MT IT QT ->
       forall (A : Type) (t : PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A) (s : S),
       @Monad.eq1 T QT (S * A) (@StateFold.interp_state S E MN T MT IT ST handle A t s)
         (@Fold.interp E MN T MT IT ST handle (S * A) (@State.run_state S E MN A t s))

